using ControlGastos.Core.Entities; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace ControlGastos.Infrastructure.Configurations;
public sealed class UsuarioTelegramConfiguration : IEntityTypeConfiguration<UsuarioTelegram> { public void Configure(EntityTypeBuilder<UsuarioTelegram> b) { b.ToTable("tbr_usuario_telegram", "finanzas"); b.HasKey(x=>x.IdUsuario); b.Property(x=>x.IdUsuario).HasColumnName("idd_usuario"); b.Property(x=>x.IdTelegram).HasColumnName("idd_telegram"); b.Property(x=>x.IdChatTelegram).HasColumnName("idd_chat_telegram"); b.Property(x=>x.NombreUsuarioTelegram).HasColumnName("nom_usuario_telegram").HasMaxLength(100); b.Property(x=>x.EstaVinculado).HasColumnName("est_vinculado"); b.Property(x=>x.FechaVinculacion).HasColumnName("fec_vinculacion"); b.Property(x=>x.FechaActualizacion).HasColumnName("fec_actualizacion"); } }
